sell_code:
regime_strong = 등락율 >= {regime_rate_min} and 체결강도 >= {regime_strength_min} and 당일거래대금각도({regime_money_angle_window}, {regime_shift}) >= {regime_money_angle_min}
if regime_strong:
    if 수익률 >= {loose_take} or 수익률 <= {loose_stop} or 보유시간 >= {loose_max_hold_sec} or (최고수익률 >= {be_trigger} and 수익률 <= {be_floor}) or (최고수익률 >= {trail_trigger} and 최고수익률 - 수익률 >= {trail_gap}):
        self.Sell()
else:
    if 수익률 >= {tight_take} or 수익률 <= {tight_stop} or 보유시간 >= {tight_max_hold_sec}:
        self.Sell()
